import { resolve } from "node:path";

export const MAX_PHOTO_BYTES = 20 * 1024 * 1024;
const fileNamePattern = /^\d{10,17}-[a-f0-9]{16,64}\.(jpg|png|webp|gif)$/;

export type PhotoReference =
  | { kind: "local" | "legacy-local"; fileName: string }
  | { kind: "blob"; pathname: string }
  | { kind: "legacy-blob"; url: string };

/** Storage references are generated by the server; arbitrary paths/URLs are never accepted. */
export function parsePhotoReference(value: string): PhotoReference | null {
  for (const [prefix, kind] of [["private-local:", "local"], ["/uploads/events/", "legacy-local"]] as const) {
    if (value.startsWith(prefix)) {
      const fileName = value.slice(prefix.length);
      return fileNamePattern.test(fileName) ? { kind, fileName } : null;
    }
  }
  if (value.startsWith("private-blob:events/")) {
    const fileName = value.slice("private-blob:events/".length);
    return fileNamePattern.test(fileName) ? { kind: "blob", pathname: `events/${fileName}` } : null;
  }
  // Compatibility for existing public Blob files. This does not revoke their public URLs.
  const match = /^https:\/\/[a-z0-9-]+\.public\.blob\.vercel-storage\.com\/events\/([^/?#]+)$/.exec(value);
  return match && fileNamePattern.test(match[1]) ? { kind: "legacy-blob", url: value } : null;
}

export function localPhotoPath(root: string, fileName: string): string {
  if (!fileNamePattern.test(fileName)) throw new Error("Invalid photo file name");
  return resolve(root, fileName);
}

export function photoContentType(reference: PhotoReference): string {
  const name = "fileName" in reference ? reference.fileName : "pathname" in reference ? reference.pathname : reference.url;
  const extension = name.split(".").at(-1);
  return ({ jpg: "image/jpeg", png: "image/png", webp: "image/webp", gif: "image/gif" } as Record<string, string>)[extension ?? ""];
}

export function matchesPhotoMime(bytes: Uint8Array, mime: string): boolean {
  const ascii = (start: number, end: number) => String.fromCharCode(...bytes.subarray(start, end));
  if (mime === "image/jpeg") return bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff;
  if (mime === "image/png") return bytes.length >= 8 && [137, 80, 78, 71, 13, 10, 26, 10].every((byte, i) => bytes[i] === byte);
  if (mime === "image/gif") return ["GIF87a", "GIF89a"].includes(ascii(0, 6));
  if (mime === "image/webp") return bytes.length >= 12 && ascii(0, 4) === "RIFF" && ascii(8, 12) === "WEBP";
  return false;
}

/** Enforce the real body size, including when Content-Length is missing or dishonest. */
export async function readPhotoFormData(request: Request): Promise<FormData> {
  const maxBodyBytes = MAX_PHOTO_BYTES + 16 * 1024;
  if (Number(request.headers.get("content-length")) > maxBodyBytes) throw new RangeError("Upload too large");
  const reader = request.body?.getReader();
  if (!reader) throw new Error("Missing upload body");
  const chunks: Uint8Array[] = [];
  let size = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > maxBodyBytes) {
        await reader.cancel();
        throw new RangeError("Upload too large");
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }
  const bytes = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
  return new Response(bytes, { headers: { "content-type": request.headers.get("content-type") ?? "" } }).formData();
}
